sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {

    // ============================================
    // 1. GET GUEST NAME
    // ============================================

    var guestName = 'Guest';

    if (current.guest) {
        var guestGR = current.guest.getRefRecord();

        if (guestGR && guestGR.isValidRecord()) {
            guestName = guestGR.getDisplayValue();
        }
    }


    // ============================================
    // 2. GET ROOM NUMBER
    // ============================================

    var roomNumber = 'Not specified';

    if (current.room) {
        var roomGR = current.room.getRefRecord();

        if (roomGR && roomGR.isValidRecord()) {

            if (roomGR.room_number) {
                roomNumber = roomGR.room_number.toString();
            }
        }
    }


    // ============================================
    // 3. EMAIL CONTENT
    // ============================================

    template.print(
        'Dear ' + guestName + ',<br><br>'
    );

    template.print(
        'Your request has been successfully registered.<br><br>'
    );

    template.print(
        '<strong>Request Number:</strong> ' +
        current.number +
        '<br>'
    );

    template.print(
        '<strong>Room:</strong> ' +
        roomNumber +
        '<br>'
    );

    template.print(
        '<strong>Status:</strong> Registered<br><br>'
    );

    template.print(
        'Our team has received your request and will assign a staff member shortly.<br>'
    );

    template.print(
        'You will receive another update once a staff member has been assigned to handle your request.<br><br>'
    );

    template.print(
        'Thank you,<br>'
    );

    template.print(
        'FlowOps Guest Services'
    );

})(current, template, email, email_action, event);
